// The archive read acceptance tests (read spec 2026-11-23, section 6 tests 1 to 9 and 11): the real path. Claude Code
// session files generated by ReadFixtureHome are backfilled with TranscriptBackfill (ingest only, no embedder), then
// transcript_search, transcript_get and transcript_sessions are called through the registry of a server composition
// built with ServerComposition.OpenLocalForCatalog. The one fixture that does not come from a session file is the
// session with a gap (and the reset and timeless rows of the session list): a unit that kept no text cannot be produced
// from a file, so those are written with ReadArchiveBuilder through the store's ApplyIngest.

namespace TotalRecall.Server.Tests;

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using System.Threading;
using System.Threading.Tasks;
using TotalRecall.Infrastructure.Transcripts;
using TotalRecall.TestSupport.Transcripts;
using Xunit;
using Xunit.Abstractions;
using SqliteOpener = TotalRecall.Infrastructure.Storage.SqliteConnection;

[Collection("process-environment-console")]
public sealed class TranscriptReadAcceptanceTests : IDisposable
{
    private const string Host = "claude-code";
    private const string OffText = "Run `total-recall transcripts enable` in a terminal to turn the archive on.";
    private const string NothingArchived = "nothing is archived yet; run total-recall transcripts backfill";
    private const string NothingArchivedSuffix = " (nothing is archived yet; run total-recall transcripts backfill)";
    private const string CutMarker = "[cut: raise max_tokens to read the rest]";
    private const int Day = 86_400;

    /// <summary>A remote provider the composition can build (no call at construction) and no allow_remote_embedding.</summary>
    private const string OpenAiEmbedding =
        "[embedding]\nprovider = \"openai\"\nendpoint = \"http://127.0.0.1:1\"\napi_key = \"x\"\n";

    private readonly ITestOutputHelper _output;
    private readonly Dictionary<string, string?> _saved = new();
    private readonly List<IDisposable> _compositions = new();
    private readonly ClaudeFixtureHome _home = new();
    private readonly string _dir = Path.Combine(Path.GetTempPath(), "tr-read-accept-" + Guid.NewGuid().ToString("N"));

    public TranscriptReadAcceptanceTests(ITestOutputHelper output) => _output = output;

    private string DataDir => Path.Combine(_dir, "data");
    private string Db => Path.Combine(DataDir, "total-recall.db");
    private string UserHome => Path.Combine(_dir, "userhome");
    private TranscriptLocation MainLocation => new(Db, IsMainDatabase: true);
    private string Alpha => Path.Combine(_home.Root, "work", "alpha");
    private string Beta => Path.Combine(_home.Root, "work", "beta");

    public void Dispose()
    {
        foreach (var c in _compositions) c.Dispose();
        foreach (var (k, v) in _saved) Environment.SetEnvironmentVariable(k, v);
        Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();
        try { Directory.Delete(_dir, recursive: true); } catch (IOException) { } catch (UnauthorizedAccessException) { }
        _home.Dispose();
    }

    private void Set(string name, string? value)
    {
        if (!_saved.ContainsKey(name)) _saved[name] = Environment.GetEnvironmentVariable(name);
        Environment.SetEnvironmentVariable(name, value);
    }

    /// <summary>
    /// The data directory with <paramref name="config"/>, HOME and USERPROFILE redirected to an empty folder, the XDG
    /// and Hermes directories to absent folders, Claude Code's directory at the fixture home; the sentinel written when
    /// <paramref name="sentinel"/> and the archive tables created in the main database when <paramref name="createArchive"/>.
    /// </summary>
    private void Setup(string config, bool sentinel = true, bool createArchive = true)
    {
        Directory.CreateDirectory(DataDir);
        Directory.CreateDirectory(UserHome);
        Set("TOTAL_RECALL_HOME", DataDir);
        Set("TOTAL_RECALL_DB_PATH", null);
        Set("HOME", UserHome);
        Set("USERPROFILE", UserHome);
        Set("CLAUDE_CONFIG_DIR", _home.Root);
        Set("XDG_CONFIG_HOME", Path.Combine(_dir, "xdg-config"));
        Set("XDG_DATA_HOME", Path.Combine(_dir, "xdg-data"));
        Set("HERMES_HOME", Path.Combine(_dir, "hermes"));
        File.WriteAllText(Path.Combine(DataDir, "config.toml"), config);
        if (sentinel) new TranscriptSentinel(DataDir).Write();
        if (createArchive)
        {
            var open = TranscriptStore.Open(MainLocation, create: true, UserHome);
            Assert.Equal(TranscriptOpenStatus.Opened, open.Status);
            open.Store!.Dispose();
        }
        Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();
    }

    /// <summary>The archive on in the main database, with the openai embedding of <see cref="OpenAiEmbedding"/>.</summary>
    private void ArchiveOn() => Setup("[transcripts]\nenabled = true\n" + OpenAiEmbedding);

    private ServerCompositionHandles Compose(string? dbPath = null)
    {
        var handles = ServerComposition.OpenLocalForCatalog(dbPath ?? Db);
        _compositions.Add(handles);
        return handles;
    }

    /// <summary>Backfills every placed session into <paramref name="location"/> (the main database by default); no embedder.</summary>
    private BackfillSummary Backfill(TranscriptLocation? location = null)
    {
        var open = TranscriptStore.Open(location ?? MainLocation, create: true, UserHome);
        Assert.Equal(TranscriptOpenStatus.Opened, open.Status);
        using var store = open.Store!;
        var summary = new TranscriptBackfill(store, new ClaudeCodeAdapter(_home.ProjectsDir), resolver: null, userHome: UserHome)
            .Run(CancellationToken.None);
        Assert.Equal(0, summary.Failed);
        Assert.Equal(0, summary.Retry);
        return summary;
    }

    /// <summary>Writes sessions with <see cref="ReadArchiveBuilder"/> into the main database.</summary>
    private void Build(Action<ReadArchiveBuilder> seed)
    {
        var open = TranscriptStore.Open(MainLocation, create: true, UserHome);
        Assert.Equal(TranscriptOpenStatus.Opened, open.Status);
        using var store = open.Store!;
        seed(new ReadArchiveBuilder(store));
    }

    /// <summary>Forgets a session through a second store on the main database, as <c>transcripts forget</c> does.</summary>
    private void Forget(string hostSessionId)
    {
        var open = TranscriptStore.Open(MainLocation, create: false, UserHome);
        Assert.Equal(TranscriptOpenStatus.Opened, open.Status);
        using var store = open.Store!;
        Assert.Equal(1, store.ForgetSession(Host, hostSessionId).Sessions);
    }

    private long Scalar(string sql, params (string Name, object Value)[] args)
    {
        using var conn = SqliteOpener.Open(Db, pooling: false);
        using var cmd = conn.CreateCommand();
        cmd.CommandText = sql;
        foreach (var (name, value) in args) cmd.Parameters.AddWithValue(name, value);
        return Convert.ToInt64(cmd.ExecuteScalar(), CultureInfo.InvariantCulture);
    }

    private long ChunkId(string hostSessionId, int exchange, int part = 0) => Scalar(
        "SELECT c.id FROM tx_chunk c JOIN tx_session s ON s.id = c.session_id " +
        "WHERE s.host_session_id = $h AND c.exchange_start = $e AND c.part = $p",
        ("$h", hostSessionId), ("$e", exchange), ("$p", part));

    /// <summary>The stored content of every part of one exchange, ascending part: the chunker's own output.</summary>
    private List<string> StoredParts(string hostSessionId, int exchange)
    {
        using var conn = SqliteOpener.Open(Db, pooling: false);
        using var cmd = conn.CreateCommand();
        cmd.CommandText =
            "SELECT c.content FROM tx_chunk c JOIN tx_session s ON s.id = c.session_id " +
            "WHERE s.host_session_id = $h AND c.exchange_start = $e ORDER BY c.part";
        cmd.Parameters.AddWithValue("$h", hostSessionId);
        cmd.Parameters.AddWithValue("$e", exchange);
        using var reader = cmd.ExecuteReader();
        var parts = new List<string>();
        while (reader.Read()) parts.Add(reader.GetString(0));
        return parts;
    }

    private string Iso(int second) => ReadArchiveBuilder.Iso(_home.BaseTime.AddSeconds(second))!;

    // ---- calls -----------------------------------------------------------------------------------------------------

    private static JsonElement? Parse(string? args) => args is null ? null : JsonDocument.Parse(args).RootElement.Clone();

    private static async Task<JsonElement> Call(ServerCompositionHandles h, string tool, string? args)
    {
        Assert.True(h.Registry.TryGet(tool, out var handler));
        var r = await handler!.ExecuteAsync(Parse(args), CancellationToken.None);
        var content = Assert.Single(r.Content);
        Assert.True(r.IsError != true, $"{tool} {args} answered an error: {content.Text}");
        return JsonDocument.Parse(content.Text).RootElement.Clone();
    }

    private static async Task<string> ErrorResult(ServerCompositionHandles h, string tool, string? args)
    {
        Assert.True(h.Registry.TryGet(tool, out var handler));
        var r = await handler!.ExecuteAsync(Parse(args), CancellationToken.None);
        Assert.True(r.IsError);
        return Assert.Single(r.Content).Text;
    }

    private static async Task<string> ArgumentError(ServerCompositionHandles h, string tool, string? args)
    {
        Assert.True(h.Registry.TryGet(tool, out var handler));
        var ex = await Assert.ThrowsAnyAsync<ArgumentException>(() => handler!.ExecuteAsync(Parse(args), CancellationToken.None));
        var r = ErrorTranslator.Translate(ex, new StringWriter());
        Assert.True(r.IsError);
        Assert.StartsWith("Invalid arguments:", Assert.Single(r.Content).Text);
        return ex.Message;
    }

    private static string GetArgs(string session, int from, int? to = null, int? context = null, int? maxTokens = null)
    {
        using var buffer = new MemoryStream();
        using (var w = new Utf8JsonWriter(buffer))
        {
            w.WriteStartObject();
            w.WriteString("session", session);
            w.WriteNumber("from_exchange", from);
            if (to is { } t) w.WriteNumber("to_exchange", t);
            if (context is { } c) w.WriteNumber("context", c);
            if (maxTokens is { } m) w.WriteNumber("max_tokens", m);
            w.WriteEndObject();
        }
        return Encoding.UTF8.GetString(buffer.ToArray());
    }

    private static string IdArgs(long id, int? context = null, int? maxTokens = null) =>
        "{\"id\":" + id.ToString(CultureInfo.InvariantCulture)
        + (context is { } c ? ",\"context\":" + c.ToString(CultureInfo.InvariantCulture) : "")
        + (maxTokens is { } m ? ",\"max_tokens\":" + m.ToString(CultureInfo.InvariantCulture) : "")
        + "}";

    private static JsonElement[] Exchanges(JsonElement get) => get.GetProperty("exchanges").EnumerateArray().ToArray();
    private static int[] Ns(JsonElement get) => Exchanges(get).Select(e => e.GetProperty("n").GetInt32()).ToArray();
    private static int[] RequestedNs(JsonElement get) =>
        Exchanges(get).Where(e => e.GetProperty("requested").GetBoolean()).Select(e => e.GetProperty("n").GetInt32()).ToArray();
    private static string TextOf(JsonElement get, int n) =>
        Exchanges(get).Single(e => e.GetProperty("n").GetInt32() == n).GetProperty("text").GetString()!;
    private static bool Truncated(JsonElement get) => get.TryGetProperty("truncated", out var t) && t.GetBoolean();
    private static int Tokens(string text) => (text.Length + 3) / 4;

    private static string[] SessionRefs(JsonElement list) =>
        list.GetProperty("sessions").EnumerateArray().Select(s => s.GetProperty("session").GetString()!).ToArray();

    /// <summary>The <c>approxTokens</c> of an answer is the sum over its texts and never exceeds the budget.</summary>
    private static void AssertBudget(JsonElement get, int maxTokens)
    {
        var tokens = get.GetProperty("approxTokens").GetInt32();
        Assert.Equal(Exchanges(get).Sum(e => Tokens(e.GetProperty("text").GetString()!)), tokens);
        Assert.True(tokens <= maxTokens, $"approxTokens {tokens} is over max_tokens {maxTokens}");
    }

    private static string Key(string hostSessionId) => Host + ":" + hostSessionId;

    private static string Dialogue(string user, string assistant) => "User: " + user + "\n\nAssistant: " + assistant;

    // ---- 1: follow a hit -------------------------------------------------------------------------------------------

    [Fact]
    public async Task FollowAHit_SearchThenGetById_ShowsExchangeWithContext()
    {
        ArchiveOn();
        ReadFixtureHome.Place(_home, Alpha, "hit", ReadFixtureHome.Dialogue(5,
            n => $"Question {n} about the importer",
            n => n == 2 ? "The duplicate check zqxneedle fails on renamed files." : $"Answer {n} about the importer."));
        ReadFixtureHome.Place(_home, Beta, "other", ReadFixtureHome.Dialogue(2, n => $"Unrelated {n}", n => $"Reply {n}"));
        Assert.Equal(2, Backfill().New);
        var h = Compose();

        var search = await Call(h, "transcript_search", "{\"query\":\"zqxneedle\",\"scope\":\"all\"}");
        Assert.Equal("off", search.GetProperty("search").GetProperty("meaning").GetString()); // words only, no embedder call
        var hit = search.GetProperty("results").EnumerateArray().First();
        Assert.Equal(Key("hit"), hit.GetProperty("session").GetString());
        Assert.Equal("2", hit.GetProperty("exchanges").GetString());
        var id = hit.GetProperty("id").GetInt64();

        var get = await Call(h, "transcript_get", IdArgs(id));

        Assert.True(get.GetProperty("enabled").GetBoolean());
        Assert.Equal(Key("hit"), get.GetProperty("session").GetString());
        Assert.Equal("alpha", get.GetProperty("project").GetString());
        Assert.Equal("interactive", get.GetProperty("kind").GetString());
        Assert.Equal("Question 0 about the importer", get.GetProperty("title").GetString());
        Assert.Equal("2", get.GetProperty("requested").GetString());
        Assert.Equal(1, get.GetProperty("context").GetInt32());
        Assert.Equal(new[] { 1, 2, 3 }, Ns(get));
        Assert.Equal(new[] { false, true, false }, Exchanges(get).Select(e => e.GetProperty("requested").GetBoolean()).ToArray());
        Assert.Equal(
            Dialogue("Question 2 about the importer", "The duplicate check zqxneedle fails on renamed files."),
            TextOf(get, 2));
        Assert.Equal(Dialogue("Question 1 about the importer", "Answer 1 about the importer."), TextOf(get, 1));
        Assert.Equal(Iso(20), Exchanges(get)[1].GetProperty("ts").GetString()); // exchange 2's user record
        Assert.False(Truncated(get));
        Assert.False(get.TryGetProperty("nextFromExchange", out _));
        AssertBudget(get, 2000);
    }

    // ---- 2: context 0 and 10 ---------------------------------------------------------------------------------------

    [Fact]
    public async Task Context0_And_Context10_NearEnds()
    {
        ArchiveOn();
        ReadFixtureHome.Place(_home, Alpha, "ctx", ReadFixtureHome.Dialogue(6, n => $"Step {n}", n => $"Done with step {n}."));
        Backfill();
        var h = Compose();

        var alone = await Call(h, "transcript_get", GetArgs(Key("ctx"), 2, context: 0));
        Assert.Equal(new[] { 2 }, Ns(alone));
        Assert.Equal(new[] { 2 }, RequestedNs(alone));
        Assert.False(Truncated(alone));

        var byId = await Call(h, "transcript_get", IdArgs(ChunkId("ctx", 3), context: 0));
        Assert.Equal(new[] { 3 }, Ns(byId));

        foreach (var n in new[] { 1, 4 })
        {
            var wide = await Call(h, "transcript_get", GetArgs(Key("ctx"), n, context: 10, maxTokens: 20000));
            Assert.Equal(new[] { 0, 1, 2, 3, 4, 5 }, Ns(wide));
            Assert.Equal(new[] { n }, RequestedNs(wide));
            Assert.False(Truncated(wide)); // the session's ends are not a truncation
            Assert.False(wide.TryGetProperty("note", out _));
        }

        var start = await Call(h, "transcript_get", IdArgs(ChunkId("ctx", 0), context: 10));
        Assert.Equal(new[] { 0, 1, 2, 3, 4, 5 }, Ns(start));
        Assert.False(Truncated(start));
    }

    // ---- 3: a session range, past the end, over a gap --------------------------------------------------------------

    [Fact]
    public async Task SessionRange_PartlyOutside_And_OverAGap()
    {
        ArchiveOn();
        ReadFixtureHome.Place(_home, Alpha, "range", ReadFixtureHome.Dialogue(6, n => $"Range question {n}", n => $"Range answer {n}."));
        Backfill();
        // Exchange 2 kept no text: no chunk, so the stored numbers have a gap.
        Build(a => a.Session(Host, "gap", project: "alpha", title: "Gap")
            .Exchange(0, "gap zero").Exchange(1, "gap one").Exchange(3, "gap three").Exchange(4, "gap four").Exchange(5, "gap five")
            .Commit());
        var h = Compose();

        var range = await Call(h, "transcript_get", GetArgs(Key("range"), 2, 3));
        Assert.Equal("2-3", range.GetProperty("requested").GetString());
        Assert.Equal(new[] { 1, 2, 3, 4 }, Ns(range));
        Assert.Equal(new[] { 2, 3 }, RequestedNs(range));
        Assert.Equal(Dialogue("Range question 3", "Range answer 3."), TextOf(range, 3));

        var outside = await Call(h, "transcript_get", GetArgs(Key("range"), 4, 9));
        Assert.Equal(new[] { 3, 4, 5 }, Ns(outside));
        Assert.Equal(new[] { 4, 5 }, RequestedNs(outside));
        Assert.False(Truncated(outside));
        Assert.False(outside.TryGetProperty("nextFromExchange", out _));

        var past = await Call(h, "transcript_get", GetArgs(Key("range"), 10, 12));
        Assert.Empty(Exchanges(past));
        Assert.Equal(0, past.GetProperty("approxTokens").GetInt32());
        Assert.False(Truncated(past));
        Assert.Equal("no stored exchange in exchanges 10-12; the session has 6 exchanges (numbered 0 to 5; some may hold no text)",
            past.GetProperty("note").GetString());

        var overGap = await Call(h, "transcript_get", GetArgs(Key("gap"), 1, 3));
        Assert.Equal(new[] { 0, 1, 3, 4 }, Ns(overGap));
        Assert.Equal(new[] { 1, 3 }, RequestedNs(overGap));
        Assert.Equal("gap three", TextOf(overGap, 3));

        // Context counts stored exchanges: the gap costs none.
        var nextToGap = await Call(h, "transcript_get", GetArgs(Key("gap"), 3, context: 2));
        Assert.Equal(new[] { 0, 1, 3, 4, 5 }, Ns(nextToGap));

        var inGap = await Call(h, "transcript_get", GetArgs(Key("gap"), 2));
        Assert.Empty(Exchanges(inGap));
        Assert.Equal("no stored exchange in exchange 2; the session has 6 exchanges (numbered 0 to 5; some may hold no text)",
            inGap.GetProperty("note").GetString());
    }

    // ---- 4: a multi-part exchange ----------------------------------------------------------------------------------

    [Fact]
    public async Task MultiPartExchange_ReadsAsOneText()
    {
        ArchiveOn();
        const string question = "Explain the long design zqxlong";
        var answer = ReadFixtureHome.Paragraphs("Design", 5, 700);
        var summary = ReadFixtureHome.Words("User: the user asked about the design. ", 1000) + "\n\n"
            + ReadFixtureHome.Words("User (continued): the summary goes on. ", 1000);
        var script = new ReadSessionScript()
            .Exchange("Short opening question", "Short opening answer.")
            .Exchange(question, answer)
            .Exchange("Short closing question", "Short closing answer.")
            .CompactionSummary(summary)
            .Exchange("After the summary", "Carry on.");
        ReadFixtureHome.Place(_home, Alpha, "long", script);
        Backfill();
        var h = Compose();

        // The chunker split exchange 1 into several parts; every later part repeats the question.
        var parts = StoredParts("long", 1);
        Assert.True(parts.Count >= 2, $"exchange 1 has {parts.Count} part(s)");
        var bodies = parts.Select(p => p[(p.IndexOf("\n\n", StringComparison.Ordinal) + 2)..]).ToList();
        Assert.All(bodies.Skip(1), b => Assert.StartsWith("User (continued): " + question + "\n\n", b, StringComparison.Ordinal));
        var rejoined = bodies[0] + string.Concat(bodies.Skip(1).Select(b => "\n\n" + b[(b.IndexOf("\n\n", StringComparison.Ordinal) + 2)..]));

        var get = await Call(h, "transcript_get", GetArgs(Key("long"), 1, context: 0, maxTokens: 20000));
        var text = TextOf(get, 1);
        Assert.Equal(rejoined, text);
        Assert.Equal(Dialogue(question, answer), text);
        Assert.DoesNotContain("User (continued):", text, StringComparison.Ordinal);
        Assert.DoesNotContain(" | exchanges ", text, StringComparison.Ordinal);
        Assert.Equal("dialogue", Exchanges(get)[0].GetProperty("chunkType").GetString());

        // Following a hit on a later part reads the whole exchange.
        var byLaterPart = await Call(h, "transcript_get", IdArgs(ChunkId("long", 1, part: parts.Count - 1), context: 0, maxTokens: 20000));
        Assert.Equal(text, TextOf(byLaterPart, 1));

        // A multi-part compaction summary that begins with "User: " and whose later part begins with the label is as stored.
        var summaryParts = StoredParts("long", 3);
        Assert.Equal(2, summaryParts.Count);
        Assert.StartsWith("User (continued): ", summaryParts[1][(summaryParts[1].IndexOf("\n\n", StringComparison.Ordinal) + 2)..],
            StringComparison.Ordinal);
        var summaryGet = await Call(h, "transcript_get", GetArgs(Key("long"), 3, context: 0, maxTokens: 20000));
        Assert.Equal("compaction-summary", Exchanges(summaryGet)[0].GetProperty("chunkType").GetString());
        Assert.Equal(summary, TextOf(summaryGet, 3));
    }

    // ---- 5: the budget and reading on ------------------------------------------------------------------------------

    /// <summary>
    /// Ten exchanges of exactly 400 characters (100 tokens) each, except exchange 3, which is about 3,000 characters and
    /// alone over a budget of 450 or 200.
    /// </summary>
    private void PlacePagingSession()
    {
        ReadFixtureHome.Place(_home, Alpha, "paging", ReadFixtureHome.Dialogue(10,
            n => $"Question {n:D2} about paging",
            n => ReadFixtureHome.Words($"Answer {n:D2}: ", n == 3 ? 3000 : 400 - Dialogue($"Question {n:D2} about paging", "").Length)));
    }

    [Fact]
    public async Task BudgetAndPaging_FromBackfilledSessions()
    {
        ArchiveOn();
        PlacePagingSession();
        Backfill();
        var h = Compose();
        var session = Key("paging");

        // A window over the budget keeps the requested exchange and drops far context first, alternating before and after.
        var window = await Call(h, "transcript_get", GetArgs(session, 6, context: 3, maxTokens: 450));
        Assert.All(Exchanges(window).Where(e => e.GetProperty("n").GetInt32() != 3),
            e => Assert.Equal(400, e.GetProperty("text").GetString()!.Length));
        Assert.Equal(new[] { 4, 5, 6, 7 }, Ns(window));
        Assert.Equal(new[] { 6 }, RequestedNs(window));
        Assert.True(Truncated(window));
        Assert.False(window.TryGetProperty("nextFromExchange", out _));
        Assert.False(window.TryGetProperty("nextToExchange", out _));
        Assert.Equal("3 context exchanges left out to fit max_tokens 450; raise max_tokens to see more context",
            window.GetProperty("note").GetString());
        AssertBudget(window, 450);

        // A first exchange alone over the budget is cut and marked, with the note; nothing follows it.
        foreach (var args in new[] { GetArgs(session, 3, maxTokens: 200), IdArgs(ChunkId("paging", 3), maxTokens: 200) })
        {
            var cut = await Call(h, "transcript_get", args);
            Assert.Equal(new[] { 3 }, Ns(cut));
            var cutText = TextOf(cut, 3);
            Assert.EndsWith(CutMarker, cutText, StringComparison.Ordinal);
            Assert.StartsWith("User: Question 03 about paging", cutText, StringComparison.Ordinal);
            Assert.True(cutText.Length <= 800);
            Assert.True(Truncated(cut));
            Assert.False(cut.TryGetProperty("nextFromExchange", out _));
            Assert.Contains("raise max_tokens to read it whole", cut.GetProperty("note").GetString(), StringComparison.Ordinal);
            AssertBudget(cut, 200);
        }

        // A requested range over the budget, read on exactly as each answer says until no pointer remains.
        var seen = new List<int>();
        var answer = await Call(h, "transcript_get", GetArgs(session, 0, 9, maxTokens: 450));
        Assert.Equal(new[] { 0, 1, 2 }, Ns(answer)); // the range ends at exchange 3, which does not fit: no context
        var calls = 1;
        var cutSeen = false;
        while (true)
        {
            AssertBudget(answer, 450);
            Assert.Equal(Ns(answer), RequestedNs(answer)); // reading on adds no context
            seen.AddRange(RequestedNs(answer));
            if (Ns(answer).Contains(3))
            {
                cutSeen = true;
                Assert.EndsWith(CutMarker, TextOf(answer, 3), StringComparison.Ordinal);
                Assert.StartsWith("exchange 3 alone is over max_tokens 450: it was returned cut",
                    answer.GetProperty("note").GetString(), StringComparison.Ordinal);
            }
            if (!answer.TryGetProperty("nextFromExchange", out var nextFrom)) break;
            Assert.True(Truncated(answer));
            var from = nextFrom.GetInt32();
            var to = answer.GetProperty("nextToExchange").GetInt32();
            Assert.Equal(9, to);
            Assert.Contains(
                $"session: {answer.GetProperty("session").GetString()}, from_exchange: {from}, to_exchange: {to}, context: 0",
                answer.GetProperty("note").GetString(), StringComparison.Ordinal);
            answer = await Call(h, "transcript_get",
                GetArgs(answer.GetProperty("session").GetString()!, from, to, context: 0, maxTokens: 450));
            Assert.True(++calls <= 10, "reading on does not end");
        }
        Assert.True(cutSeen);
        Assert.Equal(Enumerable.Range(0, 10).ToArray(), seen.ToArray()); // the union is the range, none twice, in order
        _output.WriteLine($"range 0-9 at max_tokens 450 read in {calls} calls");
    }

    // ---- 6: automated, forgotten, invalid arguments ----------------------------------------------------------------

    [Fact]
    public async Task AutomatedSession_ReadByNameAndById()
    {
        ArchiveOn();
        ReadFixtureHome.Place(_home, Alpha, "auto",
            ReadFixtureHome.Dialogue(2, n => $"Audit step {n}", n => $"Audit result {n}.", automated: true));
        ReadFixtureHome.Place(_home, Alpha, "human", ReadFixtureHome.Dialogue(1, n => "A person asks", n => "An answer."));
        Backfill();
        var h = Compose();

        var list = await Call(h, "transcript_sessions", null);
        Assert.Equal(new[] { Key("human") }, SessionRefs(list));
        Assert.Equal(1, list.GetProperty("automatedHidden").GetInt64());

        var byName = await Call(h, "transcript_get", GetArgs(Key("auto"), 0, 1));
        Assert.Equal("automated", byName.GetProperty("kind").GetString());
        Assert.Equal(new[] { 0, 1 }, Ns(byName));
        Assert.Equal(Dialogue("Audit step 1", "Audit result 1."), TextOf(byName, 1));

        var byId = await Call(h, "transcript_get", IdArgs(ChunkId("auto", 1)));
        Assert.Equal(Key("auto"), byId.GetProperty("session").GetString());
        Assert.Equal(new[] { 0, 1 }, Ns(byId));
        Assert.Equal(new[] { 1 }, RequestedNs(byId));
    }

    [Fact]
    public async Task Forgotten_ErrorAndInvalidArguments_AreErrors()
    {
        ArchiveOn();
        ReadFixtureHome.Place(_home, Alpha, "keep", ReadFixtureHome.Dialogue(3, n => $"Keep {n}", n => $"Kept {n}."));
        ReadFixtureHome.Place(_home, Alpha, "gone", ReadFixtureHome.Dialogue(3, n => $"Gone {n}", n => $"Went {n}."));
        Backfill();
        var goneChunk = ChunkId("gone", 1);
        Forget("gone");
        var h = Compose();

        Assert.Equal($"no archived session {Key("gone")}; use transcript_sessions to list sessions",
            await ErrorResult(h, "transcript_get", GetArgs(Key("gone"), 0)));
        Assert.Equal($"no archived chunk has id {goneChunk} (it may have been forgotten); use transcript_sessions to list sessions",
            await ErrorResult(h, "transcript_get", IdArgs(goneChunk)));
        Assert.Equal($"no archived session {Key("never")}; use transcript_sessions to list sessions",
            await ErrorResult(h, "transcript_get", GetArgs(Key("never"), 0)));

        var keep = Key("keep");
        foreach (var (args, name) in new (string?, string)[]
        {
            ("{\"session\":\"nocolon\",\"from_exchange\":0}", "session"),
            ($"{{\"id\":1,\"session\":\"{keep}\",\"from_exchange\":0}}", "not both"),
            ("{}", "either id"),
            (null, "either id"),
            ($"{{\"session\":\"{keep}\"}}", "from_exchange"),
            ("{\"id\":1,\"from_exchange\":0}", "from_exchange"),
            ("{\"id\":1,\"context\":11}", "context"),
            ("{\"id\":1,\"context\":1.5}", "context"),
            ("{\"id\":1,\"max_tokens\":100}", "max_tokens"),
            ("{\"id\":1,\"max_tokens\":200.9}", "max_tokens"),
            ("{\"id\":0}", "id"),
            ($"{{\"session\":\"{keep}\",\"from_exchange\":-1}}", "from_exchange"),
            ($"{{\"session\":\"{keep}\",\"from_exchange\":0,\"to_exchange\":200}}", "200"), // 201 exchanges
            ($"{{\"session\":\"{keep}\",\"from_exchange\":2,\"to_exchange\":1}}", "to_exchange"),
        })
        {
            var message = await ArgumentError(h, "transcript_get", args);
            Assert.Contains(name, message, StringComparison.Ordinal);
        }

        // A whole number written with a fraction is accepted; a range of exactly 200 is accepted.
        var whole = await Call(h, "transcript_get", $"{{\"session\":\"{keep}\",\"from_exchange\":1.0,\"context\":2.0,\"max_tokens\":2000.0}}");
        Assert.Equal(new[] { 0, 1, 2 }, Ns(whole));
        Assert.Equal(new[] { 0, 1, 2 }, Ns(await Call(h, "transcript_get", GetArgs(keep, 0, 199, context: 0))));

        foreach (var (args, name) in new (string?, string)[]
        {
            ("{\"limit\":0}", "limit"),
            ("{\"limit\":101}", "limit"),
            ("{\"limit\":1.5}", "limit"),
            ("{\"since\":\"last tuesday\"}", "since"),
            ("{\"before\":\"last tuesday\"}", "before"),
            ("{\"include_automated\":\"yes\"}", "include_automated"),
        })
        {
            var message = await ArgumentError(h, "transcript_sessions", args);
            Assert.Contains(name, message, StringComparison.Ordinal);
            if (name == "before") Assert.DoesNotContain("since", message, StringComparison.Ordinal);
        }
        Assert.Equal(new[] { keep }, SessionRefs(await Call(h, "transcript_sessions", null)));
    }

    // ---- 7: the session list ---------------------------------------------------------------------------------------

    /// <summary>
    /// Interactive sessions a1 (alpha, day 1), b1 (beta, day 2), a2 (alpha, day 3), b2 (beta, day 4), a3 (alpha, day
    /// 5) of two exchanges each; automated auto1 (alpha, day 6) and auto2 (beta, day 7); a timeless alpha session and a
    /// reset alpha row (day 9, no chunks) written with ReadArchiveBuilder. Returns each session's last activity.
    /// </summary>
    private Dictionary<string, string> PlaceSessionList()
    {
        var ended = new Dictionary<string, string>(StringComparer.Ordinal);
        void Place(string id, string cwd, int day, bool automated = false)
        {
            var script = ReadFixtureHome.Dialogue(2, n => $"Session {id} question {n}", n => $"Session {id} answer {n}.",
                startSecond: day * Day, automated: automated);
            ReadFixtureHome.Place(_home, cwd, id, script);
            ended[id] = Iso(script.LastSecond);
        }

        Place("a1", Alpha, 1);
        Place("b1", Beta, 2);
        Place("a2", Alpha, 3);
        Place("b2", Beta, 4);
        Place("a3", Alpha, 5);
        Place("auto1", Alpha, 6, automated: true);
        Place("auto2", Beta, 7, automated: true);
        Assert.Equal(7, Backfill().New);
        Build(a =>
        {
            a.Session(Host, "timeless", project: "alpha", title: "No times").Exchange(0, "timeless body").Commit();
            a.Session(Host, "reset", project: "alpha", title: "Reset", startedAt: _home.BaseTime.AddDays(9),
                endedAt: _home.BaseTime.AddDays(9)).Reset().Commit();
        });
        return ended;
    }

    [Fact]
    public async Task Sessions_NewestFirst_ProjectSinceBefore_Titles()
    {
        ArchiveOn();
        var ended = PlaceSessionList();
        var h = Compose();

        var all = await Call(h, "transcript_sessions", null);
        Assert.Equal(new[] { "a3", "b2", "a2", "b1", "a1", "timeless" }.Select(Key).ToArray(), SessionRefs(all));
        Assert.Equal(6, all.GetProperty("total").GetInt64());
        Assert.False(all.TryGetProperty("more", out _));
        Assert.Equal(2, all.GetProperty("automatedHidden").GetInt64());
        Assert.False(all.TryGetProperty("note", out _));
        var a3 = all.GetProperty("sessions")[0];
        Assert.Equal("alpha", a3.GetProperty("project").GetString());
        Assert.Equal("interactive", a3.GetProperty("kind").GetString());
        Assert.Equal("Session a3 question 0", a3.GetProperty("title").GetString());
        Assert.Equal(Iso(5 * Day), a3.GetProperty("startedAt").GetString());
        Assert.Equal(ended["a3"], a3.GetProperty("endedAt").GetString());
        Assert.Equal(2, a3.GetProperty("exchanges").GetInt32());
        Assert.Equal(2, a3.GetProperty("chunks").GetInt64());
        Assert.Equal("Session b1 question 0", all.GetProperty("sessions")[3].GetProperty("title").GetString());

        var alpha = await Call(h, "transcript_sessions", "{\"project\":\"alpha\"}");
        Assert.Equal(new[] { "a3", "a2", "a1", "timeless" }.Select(Key).ToArray(), SessionRefs(alpha));
        Assert.Equal(1, alpha.GetProperty("automatedHidden").GetInt64());

        var since = await Call(h, "transcript_sessions", $"{{\"since\":\"{ended["a2"]}\"}}");
        Assert.Equal(new[] { "a3", "b2", "a2" }.Select(Key).ToArray(), SessionRefs(since)); // at or after: a2 included

        var before = await Call(h, "transcript_sessions", $"{{\"before\":\"{ended["a2"]}\"}}");
        Assert.Equal(new[] { "b1", "a1" }.Select(Key).ToArray(), SessionRefs(before)); // strictly before: a2 left out

        var window = await Call(h, "transcript_sessions", $"{{\"since\":\"{ended["b1"]}\",\"before\":\"{ended["a3"]}\"}}");
        Assert.Equal(new[] { "b2", "a2", "b1" }.Select(Key).ToArray(), SessionRefs(window));

        var dateOnly = await Call(h, "transcript_sessions", "{\"since\":\"2026-01-06\",\"project\":\"beta\",\"include_automated\":true}");
        Assert.Equal(new[] { "auto2" }.Select(Key).ToArray(), SessionRefs(dateOnly));

        var none = await Call(h, "transcript_sessions", "{\"project\":\"gamma\"}");
        Assert.Equal(0, none.GetProperty("total").GetInt64());
        Assert.Empty(SessionRefs(none));
        Assert.False(none.TryGetProperty("note", out _));
        Assert.False(none.TryGetProperty("automatedHidden", out _));
    }

    [Fact]
    public async Task Sessions_LimitMoreAutomatedHidden_ResetRowAbsent()
    {
        ArchiveOn();
        var ended = PlaceSessionList();
        var h = Compose();

        var limited = await Call(h, "transcript_sessions", "{\"limit\":2}");
        Assert.Equal(new[] { "a3", "b2" }.Select(Key).ToArray(), SessionRefs(limited));
        Assert.Equal(6, limited.GetProperty("total").GetInt64());
        Assert.Equal(4, limited.GetProperty("more").GetInt64());
        Assert.Equal(2, limited.GetProperty("automatedHidden").GetInt64());
        Assert.Contains("narrow with project, since or before", limited.GetProperty("note").GetString(), StringComparison.Ordinal);

        // Paging with before set to the oldest listed session's endedAt reaches every timed session once.
        var paged = new List<string>(SessionRefs(limited));
        var page = limited;
        while (page.TryGetProperty("more", out _))
        {
            var oldest = page.GetProperty("sessions").EnumerateArray().Last().GetProperty("endedAt").GetString();
            page = await Call(h, "transcript_sessions", $"{{\"limit\":2,\"before\":\"{oldest}\"}}");
            paged.AddRange(SessionRefs(page));
            Assert.True(paged.Count <= 10);
        }
        Assert.Equal(new[] { "a3", "b2", "a2", "b1", "a1" }.Select(Key).ToArray(), paged.ToArray());
        Assert.Equal(ended["a1"], page.GetProperty("sessions")[0].GetProperty("endedAt").GetString());

        var shown = await Call(h, "transcript_sessions", "{\"include_automated\":true}");
        Assert.Equal(new[] { "auto2", "auto1", "a3", "b2", "a2", "b1", "a1", "timeless" }.Select(Key).ToArray(), SessionRefs(shown));
        Assert.Equal(8, shown.GetProperty("total").GetInt64());
        Assert.False(shown.TryGetProperty("automatedHidden", out _));
        Assert.Equal("automated", shown.GetProperty("sessions")[0].GetProperty("kind").GetString());
        Assert.DoesNotContain(Key("reset"), SessionRefs(shown)); // a reset row holds nothing to read
    }

