    [Fact]
    public async Task Off_AnswersOffText_FollowsEnableAndDisable_NoFileOpened()
    {
        var archive = Path.Combine(_dir, "separate", "archive.db");
        Directory.CreateDirectory(Path.GetDirectoryName(archive)!);
        Setup("[transcripts]\nenabled = true\ndb_path = \"" + archive.Replace("\\", "/", StringComparison.Ordinal) + "\"\n"
              + OpenAiEmbedding, sentinel: false, createArchive: false);
        var sentinel = new TranscriptSentinel(DataDir);
        var h = Compose();

        async Task AssertOff()
        {
            foreach (var (tool, args) in new (string, string?)[]
                     { ("transcript_get", "{\"id\":1}"), ("transcript_get", null), ("transcript_sessions", null), ("transcript_sessions", "{\"limit\":0}") })
            {
                var off = await Call(h, tool, args);
                Assert.Equal(2, off.EnumerateObject().Count());
                Assert.False(off.GetProperty("enabled").GetBoolean());
                Assert.Equal(OffText, off.GetProperty("hint").GetString());
            }
        }

        await AssertOff();
        Assert.False(File.Exists(archive));

        sentinel.Write(); // `transcripts enable`: no restart
        var empty = await Call(h, "transcript_sessions", null);
        Assert.True(empty.GetProperty("enabled").GetBoolean());
        Assert.Equal(0, empty.GetProperty("total").GetInt64());
        Assert.Equal(NothingArchived, empty.GetProperty("note").GetString());
        Assert.Equal($"no archived session {Key("x")}; use transcript_sessions to list sessions" + NothingArchivedSuffix,
            await ErrorResult(h, "transcript_get", GetArgs(Key("x"), 0)));
        Assert.False(File.Exists(archive)); // read with create: false

        ReadFixtureHome.Place(_home, Alpha, "sep", ReadFixtureHome.Dialogue(2, n => $"Separate {n}", n => $"File {n}."));
        Backfill(new TranscriptLocation(archive, IsMainDatabase: false));
        Assert.Equal(new[] { Key("sep") }, SessionRefs(await Call(h, "transcript_sessions", null)));
        Assert.Equal(new[] { 0, 1 }, Ns(await Call(h, "transcript_get", GetArgs(Key("sep"), 0, context: 1))));

        sentinel.Remove(); // `transcripts disable`
        await AssertOff();
        sentinel.Write();
        Assert.Equal(new[] { Key("sep") }, SessionRefs(await Call(h, "transcript_sessions", null)));
    }

