    [Fact]
    public void RegistryAndCatalogAgree()
    {
        ArchiveOn();
        var h = Compose();

        var registered = h.Registry.ListTools().Where(t => t.Name.StartsWith("transcript_", StringComparison.Ordinal)).ToArray();
        Assert.Equal(new[] { "transcript_search", "transcript_get", "transcript_sessions" }, registered.Select(t => t.Name).ToArray());

        using var catalog = JsonDocument.Parse(File.ReadAllText(CatalogPath()));
        var committed = catalog.RootElement.GetProperty("tools").EnumerateArray()
            .Where(t => t.GetProperty("name").GetString()!.StartsWith("transcript_", StringComparison.Ordinal)).ToArray();
        Assert.Equal(registered.Select(t => t.Name).ToArray(), committed.Select(t => t.GetProperty("name").GetString()).ToArray());
        for (var i = 0; i < registered.Length; i++)
        {
            Assert.Equal(registered[i].Description, committed[i].GetProperty("description").GetString());
            Assert.True(JsonElement.DeepEquals(registered[i].InputSchema, committed[i].GetProperty("inputSchema")),
                $"{registered[i].Name}: the registered schema differs from catalog.json (regenerate it with dump-catalog)");
        }
    }

    private static string CatalogPath() => Path.Combine(RepoRoot(), "catalog.json");

    private static string RepoRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null)
        {
            if (File.Exists(Path.Combine(dir.FullName, "catalog.json")) && Directory.Exists(Path.Combine(dir.FullName, "src")))
                return dir.FullName;
            dir = dir.Parent;
        }
        throw new DirectoryNotFoundException("the repository root was not found walking up from " + AppContext.BaseDirectory);
    }

    // ---- 9: read-only and consistent -------------------------------------------------------------------------------

    [Fact]
    public async Task ReadDuringIngest_Succeeds_ChangesNothing()
    {
        ArchiveOn();
        ReadFixtureHome.Place(_home, Alpha, "busy", ReadFixtureHome.Dialogue(3, n => $"Busy {n}", n => $"Answer {n}."));
        Backfill();
        var h = Compose();
        var before = ArchiveSnapshot.Read(Db, includeIds: true);

        using (var writer = SqliteOpener.Open(Db, pooling: false))
        {
            // Another connection holds a write transaction with uncommitted archive changes, as an ingest does.
            using (var begin = writer.CreateCommand())
            {
                begin.CommandText = "BEGIN IMMEDIATE; UPDATE tx_chunk SET content = content || ' zqxuncommitted'; " +
                                    "UPDATE tx_session SET title = 'zqxuncommitted';";
                begin.ExecuteNonQuery();
            }

            var get = await Call(h, "transcript_get", GetArgs(Key("busy"), 1));
            Assert.Equal(new[] { 0, 1, 2 }, Ns(get));
            Assert.Equal(Dialogue("Busy 1", "Answer 1."), TextOf(get, 1));
            Assert.Equal("Busy 0", get.GetProperty("title").GetString());
            var list = await Call(h, "transcript_sessions", null);
            Assert.Equal(new[] { Key("busy") }, SessionRefs(list));
            Assert.Equal("Busy 0", list.GetProperty("sessions")[0].GetProperty("title").GetString());

            using var rollback = writer.CreateCommand();
            rollback.CommandText = "ROLLBACK;";
            rollback.ExecuteNonQuery();
        }

        await Call(h, "transcript_get", IdArgs(ChunkId("busy", 2)));
        var after = ArchiveSnapshot.Read(Db, includeIds: true);
        Assert.Equal(before.Sessions, after.Sessions);
        Assert.Equal(before.Chunks, after.Chunks);
    }

