    // ---- 11: no embedding provider touched -------------------------------------------------------------------------

    [Fact]
    public async Task NoEmbeddingProviderTouched()
    {
        // The archive in its own file, so the second composition can use a fresh main database (switching the
        // provider of one main database would start a memory re-index, which is not what this test is about).
        var archive = Path.Combine(_dir, "separate", "archive.db");
        Directory.CreateDirectory(Path.GetDirectoryName(archive)!);
        var archiveSetting = "[transcripts]\nenabled = true\ndb_path = \"" + archive.Replace("\\", "/", StringComparison.Ordinal) + "\"\n";

        // With a remote provider (no allow_remote_embedding) both tools answer from the archive.
        Setup(archiveSetting + OpenAiEmbedding, createArchive: false);
        ReadFixtureHome.Place(_home, Alpha, "plain", ReadFixtureHome.Dialogue(2, n => $"Plain {n}", n => $"Text {n}."));
        Backfill(new TranscriptLocation(archive, IsMainDatabase: false));
        await AssertBothToolsAnswer(Compose());

        // Again with the local provider and an empty home, so no model override exists.
        File.WriteAllText(Path.Combine(DataDir, "config.toml"), archiveSetting);
        var emptyHome = Path.Combine(_dir, "empty-home");
        Directory.CreateDirectory(emptyHome);
        Set("HOME", emptyHome);
        Set("USERPROFILE", emptyHome);
        await AssertBothToolsAnswer(Compose(Path.Combine(DataDir, "local.db")));

        // The read path takes no embedder: nothing it is built from names one.
        foreach (var type in new[] { typeof(TranscriptReadService), typeof(TranscriptReadContext) })
        {
            var mentioned = type.GetConstructors().SelectMany(c => c.GetParameters()).Select(p => p.ParameterType)
                .Concat(type.GetProperties().Select(p => p.PropertyType))
                .Concat(type.GetMethods().Where(m => m.DeclaringType == type).SelectMany(m => m.GetParameters()).Select(p => p.ParameterType))
                .Concat(type.GetMethods().Where(m => m.DeclaringType == type).Select(m => m.ReturnType))
                .Select(t => t.FullName ?? t.Name)
                .ToArray();
            Assert.DoesNotContain(mentioned, n => n.Contains("IEmbedder", StringComparison.Ordinal));
            Assert.DoesNotContain(mentioned, n => n.Contains("EmbeddingConfig", StringComparison.Ordinal));
        }

        var transcripts = Path.Combine(RepoRoot(), "src", "TotalRecall.Infrastructure", "Transcripts");
        foreach (var file in new[] { "TranscriptReadService.cs", "TranscriptReads.cs", "ExchangeText.cs" })
        {
            var source = File.ReadAllText(Path.Combine(transcripts, file));
            foreach (var name in new[] { "IEmbedder", "HttpClient", "EmbedderFactory" })
                Assert.False(Regex.IsMatch(source, @"\b" + name + @"\b"), $"{file} names {name}");
        }
    }

    private async Task AssertBothToolsAnswer(ServerCompositionHandles h)
    {
        var get = await Call(h, "transcript_get", GetArgs(Key("plain"), 0, 1));
        Assert.Equal(new[] { 0, 1 }, Ns(get));
        Assert.Equal(Dialogue("Plain 1", "Text 1."), TextOf(get, 1));
        var list = await Call(h, "transcript_sessions", null);
        Assert.Equal(new[] { Key("plain") }, SessionRefs(list));
    }
